<script setup>
import { computed,onMounted,ref } from 'vue'
import { internalApi } from '../../internalEvaluationApi'
const tasks=ref([]),taskId=ref(''),task=ref(null),sheetId=ref(''),sheet=ref(null),message=ref(''),materials=ref([]),materialEntry=ref(null)
const editable=computed(()=>sheet.value&&['NOT_STARTED','DRAFT','RETURNED'].includes(sheet.value.status))
const total=computed(()=>sheet.value?.entries?.reduce((sum,x)=>sum+Number(x.score||0),0)||0)
async function loadTasks(){try{tasks.value=(await internalApi.tasks()).filter(x=>x.status!=='DRAFT'&&x.status!=='CANCELLED');if(tasks.value.length){taskId.value=tasks.value[0].id;await loadTask()}}catch(e){message.value=e.message}}
async function loadTask(){if(!taskId.value)return;try{task.value=await internalApi.task(taskId.value);const first=task.value.organizations.find(x=>x.score_sheet_id);sheetId.value=first?.score_sheet_id||'';if(sheetId.value)await loadSheet();else sheet.value=null}catch(e){message.value=e.message}}
async function loadSheet(){try{sheet.value=await internalApi.sheet(sheetId.value)}catch(e){message.value=e.message}}
async function save(){try{sheet.value=await internalApi.saveScores(sheet.value.id,{sheetRowVersion:sheet.value.row_version,entries:sheet.value.entries.map(x=>({entryId:x.id,score:Number(x.score||0),basisType:x.basis_type||'NONE',scoreBasis:x.score_basis,remarks:x.remarks,vetoTriggered:Boolean(x.veto_triggered),rowVersion:x.row_version}))});message.value='评分已暂存';await loadTask()}catch(e){message.value=e.message}}
async function submit(){const opinion=prompt('提交说明','评分完成，提交复核');if(opinion===null)return;try{sheet.value=await internalApi.submit(sheet.value.id,{opinion,rowVersion:sheet.value.row_version});await loadTask()}catch(e){message.value=e.message}}
async function review(action){const opinion=prompt(action==='CONFIRM'?'请输入确认意见':'请输入退回意见');if(!opinion)return;try{sheet.value=await internalApi.review(sheet.value.id,{action,opinion,rowVersion:sheet.value.row_version});await loadTask()}catch(e){message.value=e.message}}
async function upload(entry,event){const file=event.target.files?.[0];if(!file)return;try{await internalApi.upload(entry.id,file,'在线评分佐证');message.value='材料已上传';await loadSheet()}catch(e){message.value=e.message}finally{event.target.value=''}}
async function openMaterials(entry){try{materialEntry.value=entry;materials.value=await internalApi.materials(entry.id)}catch(e){message.value=e.message}}
function rules(entry){try{return JSON.parse(entry.rules_json||'[]')}catch{return []}}
onMounted(loadTasks)
</script>
<template><section class="page active">
  <div class="alert alert-info">按任务快照逐项评分。得分范围为0～标准分；提交后只读，复核退回后才可修改。评分规则仅展示，暂不自动算分。</div><div v-if="message" class="alert alert-warning">{{message}}</div>
  <div class="card"><div class="card-header"><h3>✍️ 编办在线打分评价</h3><span class="extra">张主任 / SQLite实时保存</span></div><div class="search-bar"><div class="form-item"><label>评价任务</label><select v-model="taskId" @change="loadTask"><option v-for="t in tasks" :key="t.id" :value="t.id">{{t.task_name}}（{{t.status}}）</option></select></div><div class="form-item"><label>参评机构</label><select v-model="sheetId" @change="loadSheet"><option v-for="org in task?.organizations||[]" :key="org.id" :value="org.score_sheet_id">{{org.unit_name}}（{{org.score_status}}）</option></select></div><button class="btn btn-outline" @click="loadSheet">刷新</button></div></div>
  <div v-if="sheet" class="stat-grid"><div class="stat-card"><div class="num">{{total.toFixed(1)}}</div><div class="label">机构总分</div><div class="sub">逐项得分合计</div></div><div class="stat-card"><div class="num green">{{sheet.entries.length}}</div><div class="label">评分指标</div><div class="sub">发布任务快照</div></div><div class="stat-card"><div class="num orange">{{sheet.entries.reduce((n,x)=>n+Number(x.material_count||0),0)}}</div><div class="label">佐证材料</div><div class="sub">有效附件</div></div><div class="stat-card"><div class="num">{{sheet.status}}</div><div class="label">评分状态</div><div class="sub">{{sheet.unit_name}}</div></div></div>
  <div v-if="sheet" class="card"><div class="card-header"><h3>逐项评分</h3><div class="btn-group"><button class="btn btn-primary" :disabled="!editable" @click="save">暂存评分</button><button class="btn btn-outline" :disabled="sheet.status!=='DRAFT'" @click="submit">提交复核</button><button v-if="sheet.status==='SUBMITTED'" class="btn btn-outline" @click="review('RETURN')">退回修改</button><button v-if="sheet.status==='SUBMITTED'" class="btn btn-primary" @click="review('CONFIRM')">确认完成</button></div></div><div class="table-scroll"><table><thead><tr><th>指标</th><th>标准分/权重</th><th>评分规则</th><th>本次得分</th><th>依据类型</th><th>扣加分依据</th><th>备注/否决</th><th>材料</th></tr></thead><tbody><tr v-for="entry in sheet.entries" :key="entry.id"><td><strong>{{entry.indicator_name}}</strong><div class="sub">{{entry.indicator_code}} / {{entry.evaluation_method||'-'}}</div></td><td>{{entry.standard_score}} / {{entry.weight}}%</td><td><div v-if="!rules(entry).length">无启用规则</div><div v-for="rule in rules(entry)" :key="rule.rule_name" class="tag tag-warning">{{rule.rule_type}}：{{rule.rule_name}}</div></td><td><input v-model.number="entry.score" type="number" min="0" :max="entry.standard_score" step="0.1" :disabled="!editable" style="width:82px"></td><td><select v-model="entry.basis_type" :disabled="!editable"><option value="NONE">无调整</option><option value="DEDUCTION">扣分</option><option value="BONUS">加分</option><option value="VETO">一票否决</option></select></td><td><input v-model.trim="entry.score_basis" :disabled="!editable" placeholder="填写依据"></td><td><input v-model.trim="entry.remarks" :disabled="!editable" placeholder="备注"><label><input v-model="entry.veto_triggered" type="checkbox" :disabled="!editable"> 人工确认触发否决</label></td><td><div class="btn-group"><label class="btn btn-sm btn-outline" :class="{disabled:!editable}">上传<input type="file" hidden :disabled="!editable" @change="upload(entry,$event)"></label><button class="btn btn-sm btn-outline" @click="openMaterials(entry)">查看({{entry.material_count}})</button></div></td></tr></tbody></table></div></div>
  <div v-if="sheet" class="card"><div class="card-header"><h3>🧾 状态与复核留痕</h3></div><div v-for="item in sheet.history" :key="item.id" class="version-item"><span>{{item.from_status||'新建'}} → {{item.to_status}} / {{item.reason||'-'}}</span><span>{{item.operator_name}} {{item.changed_at}}</span></div><div v-if="!sheet.history.length" class="empty">暂无状态历史</div></div>
  <div v-if="materialEntry" class="evidence-modal show" @click.self="materialEntry=null"><div class="evidence-panel"><div class="panel-head"><h3>{{materialEntry.indicator_name}} / 佐证材料</h3><button class="btn btn-outline" @click="materialEntry=null">关闭</button></div><div class="panel-body"><div v-if="!materials.length" class="empty">暂无材料</div><div v-for="file in materials" :key="file.attachment_id" class="version-item"><span>{{file.original_name}} / {{Math.ceil(file.file_size/1024)}}KB</span><div class="btn-group"><a v-if="['pdf','png','jpg','jpeg'].includes(file.extension)" class="btn btn-sm btn-outline" :href="internalApi.download(file.attachment_id,true)" target="_blank">预览</a><a class="btn btn-sm btn-outline" :href="internalApi.download(file.attachment_id)">下载</a></div></div></div></div></div>
  <div v-if="!sheet" class="card empty">请选择已发布任务和参评机构；草稿任务需先在m2-5发布。</div>
</section></template>
